package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Node_hasAttr_TriageGen2Test {

    private Node node;

    @Before
    public void setUp() {
        // Create a mock instance of Attributes
        Attributes attributes = mock(Attributes.class);

        // Initialize the Node with a base URI and attributes
        node = mock(Node.class);
        when(node.attributes()).thenReturn(attributes);
    }

    @Test
    public void testHasAttr_WhenAttributeExists_ShouldReturnTrue() {
        // Arrange
        String attributeKey = "class";
        when(node.hasAttr(attributeKey)).thenCallRealMethod();
        when(node.attributes().hasKey(attributeKey)).thenReturn(true);

        // Act
        boolean result = node.hasAttr(attributeKey);

        // Assert
        assertTrue(result);
    }

    @Test
    public void testHasAttr_WhenAttributeDoesNotExist_ShouldReturnFalse() {
        // Arrange
        String attributeKey = "id";
        when(node.hasAttr(attributeKey)).thenCallRealMethod();
        when(node.attributes().hasKey(attributeKey)).thenReturn(false);

        // Act
        boolean result = node.hasAttr(attributeKey);

        // Assert
        assertFalse(result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testHasAttr_WhenAttributeKeyIsNull_ShouldThrowIllegalArgumentException() {
        // Arrange
        String attributeKey = null;
        when(node.hasAttr(attributeKey)).thenCallRealMethod();

        // Act
        node.hasAttr(attributeKey);
    }

    @Test
    public void testHasAttr_WhenAttributeKeyIsEmpty_ShouldReturnFalse() {
        // Arrange
        String attributeKey = "";
        when(node.hasAttr(attributeKey)).thenCallRealMethod();
        when(node.attributes().hasKey(attributeKey)).thenReturn(false);

        // Act
        boolean result = node.hasAttr(attributeKey);

        // Assert
        assertFalse(result);
    }
}
